   679	def select_related_jobs(current_job: Job, jobs: list[Job], limit: int = 3) -> list[Job]:
   680	    current_slug = clean_text(current_job.meta.get("slug"))
   681	    current_role = clean_text(current_job.meta.get("roleGroupKey"))
   682	    current_location = clean_text(current_job.meta.get("locationGroupKey"))
   683	    ranked: list[tuple[int, int, int, int, Job]] = []
   684	
   685	    for candidate in jobs:
   686	        if candidate.effective_status != "active":
   687	            continue
   688	        if clean_text(candidate.meta.get("slug")) == current_slug:
   689	            continue
   690	
   691	        score = 0
   692	        if clean_text(candidate.meta.get("roleGroupKey")) == current_role:
   693	            score += 4
   694	        if clean_text(candidate.meta.get("locationGroupKey")) == current_location:
   695	            score += 2
   696	        if candidate.meta.get("featured"):
   697	            score += 1
   698	
   699	        publish_rank = int(candidate.publish_date.strftime("%Y%m%d"))
   700	        salary_rank = int(candidate.meta.get("salaryMax") or 0)
   701	        deadline_rank = int(candidate.deadline.strftime("%Y%m%d"))
   702	        ranked.append((score, publish_rank, salary_rank, deadline_rank, candidate))
   703	
   704	    ranked.sort(
   705	        key=lambda item: (
   706	            -item[0],
   707	            -item[1],
   708	            -item[2],
   709	            item[3],
   710	            item[4].meta["title"],
   711	        )
   712	    )
   713	    return [item[4] for item in ranked[:limit]]
