   800	def mask_email(value: str) -> str:
   801	    email = clean_text(value)
   802	    if not email or "@" not in email:
   803	        return "********@*****.***"
   804	    local, domain = email.split("@", 1)
   805	    local_visible = local[:2] if len(local) >= 2 else local[:1]
   806	    domain_parts = domain.split(".")
   807	    domain_name = domain_parts[0] if domain_parts else domain
   808	    domain_ext = ".".join(domain_parts[1:]) if len(domain_parts) > 1 else ""
   809	    domain_visible = domain_name[:2] if len(domain_name) >= 2 else domain_name[:1]
   810	    local_mask = local_visible + "*" * max(4, len(local) - len(local_visible))
   811	    domain_mask = domain_visible + "*" * max(4, len(domain_name) - len(domain_visible))
   812	    if domain_ext:
   813	        return f"{local_mask}@{domain_mask}.{domain_ext}"
   814	    return f"{local_mask}@{domain_mask}"
